INSERT INTO sys_menu_api (menu_id,api_id) SELECT m.id,a.id FROM sys_menu m JOIN sys_api a ON a.path LIKE '/api/gb28181/zlm/%' AND a.method='GET' WHERE (m.path='/gb28181/zlm/overview' AND a.path IN ('/api/gb28181/zlm/overview','/api/gb28181/zlm/nodes','/api/gb28181/zlm/nodes/:id/runtime')) OR (m.path='/gb28181/zlm/nodes' AND a.path IN ('/api/gb28181/zlm/nodes','/api/gb28181/zlm/nodes/:id','/api/gb28181/zlm/nodes/:id/config')) OR (m.path='/gb28181/zlm/runtime' AND a.path IN ('/api/gb28181/zlm/nodes','/api/gb28181/zlm/nodes/:id/runtime')) OR (m.path='/gb28181/zlm/streams' AND a.path IN ('/api/gb28181/zlm/nodes','/api/gb28181/zlm/streams','/api/gb28181/zlm/nodes/:id/streams','/api/gb28181/zlm/nodes/:id/streams/detail','/api/gb28181/zlm/nodes/:id/streams/viewers')) OR (m.path='/gb28181/zlm/sessions' AND a.path IN ('/api/gb28181/zlm/nodes','/api/gb28181/zlm/nodes/:id/sessions/network','/api/gb28181/zlm/nodes/:id/sessions/viewers')) OR (m.path='/gb28181/zlm/proxies' AND a.path IN ('/api/gb28181/zlm/nodes','/api/gb28181/zlm/nodes/:id/proxies/pull','/api/gb28181/zlm/nodes/:id/proxies/pull/:key','/api/gb28181/zlm/nodes/:id/proxies/push','/api/gb28181/zlm/nodes/:id/proxies/push/:key')) OR (m.path='/gb28181/zlm/ffmpeg-sources' AND a.path IN ('/api/gb28181/zlm/nodes','/api/gb28181/zlm/nodes/:id/ffmpeg-sources')) OR (m.path='/gb28181/zlm/rtp-servers' AND a.path IN ('/api/gb28181/zlm/nodes','/api/gb28181/zlm/nodes/:id/rtp-servers')) OR (m.path='/gb28181/zlm/config' AND a.path IN ('/api/gb28181/zlm/nodes','/api/gb28181/zlm/nodes/:id/config')) OR (m.path='/gb28181/zlm/scheduler' AND a.path='/api/gb28181/zlm/scheduler') OR (m.path='/gb28181/zlm/scheduler/logs' AND a.path IN ('/api/gb28181/zlm/nodes','/api/gb28181/zlm/scheduler/logs')) ON CONFLICT DO NOTHING;
